// n8n Code node (Run Once for All Items): one SAM.gov search per NAICS code.
// Edit NAICS_CODES / LOOKBACK_DAYS to change what the scout watches.
const NAICS_CODES = [
  '541511', // Custom computer programming services
  '541512', // Computer systems design services
  '541519', // Other computer related services
  '518210', // Data processing, hosting, and related services
];
const LOOKBACK_DAYS = 3; // overlaps the daily schedule so a missed day is still covered

const fmt = (d) =>
  `${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getDate()).padStart(2, '0')}/${d.getFullYear()}`;

const to = new Date();
const from = new Date(to.getTime() - LOOKBACK_DAYS * 24 * 60 * 60 * 1000);

return NAICS_CODES.map((ncode) => ({
  json: {
    url: 'https://api.sam.gov/opportunities/v2/search',
    ncode,
    postedFrom: fmt(from),
    postedTo: fmt(to),
  },
}));

// n8n Code node (Run Once for All Items): flatten SAM.gov search responses into one
// item per opportunity worth analysing. Read-only against the "seen" list: a notice is
// only marked seen after it has been analysed (see validate.js), so a failed run retries.
const KEEP_TYPES = new Set([
  'Solicitation',
  'Combined Synopsis/Solicitation',
  'Presolicitation',
  'Sources Sought',
]);
const MAX_PER_RUN = 25; // bounds LLM spend on a busy day; the rest are picked up next run

const seen = new Set($getWorkflowStaticData('global').analyzedNoticeIds || []);
const now = Date.now();
const byId = new Map();

for (const item of $input.all()) {
  for (const o of item.json.opportunitiesData || []) {
    if (!o.noticeId || byId.has(o.noticeId) || seen.has(o.noticeId)) continue;
    if (o.active !== 'Yes' || !KEEP_TYPES.has(o.type)) continue;
    const deadline = o.responseDeadLine || null;
    if (deadline && Date.parse(deadline) < now) continue;

    const place = o.placeOfPerformance || {};
    byId.set(o.noticeId, {
      noticeId: o.noticeId,
      title: o.title || '(untitled)',
      solicitationNumber: o.solicitationNumber || '',
      agency: (o.fullParentPathName || '').split('.').filter(Boolean).join(' > '),
      postedDate: o.postedDate || '',
      noticeType: o.type,
      deadline,
      naics: o.naicsCode || '',
      setAside: o.typeOfSetAsideDescription || '',
      location: [place.city && place.city.name, place.state && place.state.code].filter(Boolean).join(', '),
      uiLink: o.uiLink || '',
      descriptionUrl: typeof o.description === 'string' && o.description.startsWith('http') ? o.description : '',
    });
  }
}

return [...byId.values()]
  .sort((a, b) => b.postedDate.localeCompare(a.postedDate))
  .slice(0, MAX_PER_RUN)
  .map((json) => ({ json }));

// n8n Code node (Run Once for Each Item): turn one opportunity plus its fetched
// description into an Anthropic Messages request. The model must answer through a
// forced tool call, so the output is structured JSON rather than prose to be parsed.
// eval/run-eval.js loads this same file, so the eval always tests the production prompt.
const MODEL = 'claude-sonnet-5-5';
const MAX_SOURCE_CHARS = 24000;

// Who "we" are. Change this and the scoring changes with it.
const COMPANY_PROFILE = `We are a software vendor that replaces legacy federal systems with modern web
applications: citizen-facing portals, benefits and case-management systems, ticketing and
marketplace platforms, and AI-assisted document workflows. We are strongest at custom software
development, modernization, system integration, and data/analytics work. We are not a hardware
reseller, staffing agency, or facilities contractor. Contracts needing an active security clearance
are out of reach for us unless the document says otherwise.`;

const SYSTEM = `You do the first-pass read of a US federal procurement notice for a bid team.
Use ONLY the document and metadata provided. If something is not stated, answer null. Never guess a
deadline, set-aside, or requirement. Every requirement you list must carry a short evidence_quote
copied VERBATIM from the document. A bid team will act on your recommendation, so be conservative:
prefer "review" over "pursue" when the document is thin or ambiguous.

Company profile:
${COMPANY_PROFILE}`;

const TOOL = {
  name: 'record_analysis',
  description: 'Record the first-pass analysis of a procurement notice.',
  input_schema: {
    type: 'object',
    required: ['summary', 'scope_type', 'key_requirements', 'fit_score', 'recommendation', 'rationale', 'risks'],
    properties: {
      summary: { type: 'string', description: 'What the agency wants, in at most 50 words.' },
      scope_type: {
        type: 'string',
        enum: ['software_development', 'modernization', 'integration', 'data_analytics', 'ai_ml', 'infrastructure', 'staffing', 'hardware', 'other'],
      },
      key_requirements: {
        type: 'array',
        maxItems: 6,
        items: {
          type: 'object',
          required: ['requirement', 'evidence_quote'],
          properties: {
            requirement: { type: 'string' },
            evidence_quote: { type: 'string', description: 'Verbatim excerpt from the document supporting this requirement.' },
          },
        },
      },
      deadline_stated: { type: ['string', 'null'], description: 'Response deadline as YYYY-MM-DD if the document states one, else null.' },
      set_aside: { type: ['string', 'null'] },
      clearance_required: { type: ['boolean', 'null'] },
      fit_score: { type: 'integer', minimum: 0, maximum: 100 },
      recommendation: { type: 'string', enum: ['pursue', 'review', 'skip'] },
      rationale: { type: 'string', description: 'Two sentences on why, referring to the company profile.' },
      risks: { type: 'array', maxItems: 4, items: { type: 'string' } },
    },
  },
};

const opp = $('Normalize & dedupe').item.json;
const raw = String($json.description ?? $json.data ?? '');

const text = raw
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|li|tr|h\d)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n+/g, '\n')
  .trim();

const truncated = text.length > MAX_SOURCE_CHARS;
const source_text = truncated ? text.slice(0, MAX_SOURCE_CHARS) : text;
const thin_source = source_text.length < 300;

const metadata = [
  `Title: ${opp.title}`,
  `Agency: ${opp.agency}`,
  `Notice type: ${opp.noticeType}`,
  `Solicitation number: ${opp.solicitationNumber}`,
  `NAICS: ${opp.naics}`,
  `Set-aside (from metadata): ${opp.setAside || 'none listed'}`,
  `Response deadline (from metadata): ${opp.deadline || 'none listed'}`,
  `Place of performance: ${opp.location || 'not listed'}`,
].join('\n');

const content =
  `<metadata>\n${metadata}\n</metadata>\n\n<document>\n${source_text || '(no description text was available)'}\n</document>`;

return {
  json: {
    opp,
    source_text,
    truncated,
    thin_source,
    request: {
      model: MODEL,
      max_tokens: 1500,
      system: SYSTEM,
      tools: [TOOL],
      tool_choice: { type: 'tool', name: 'record_analysis' },
      messages: [{ role: 'user', content }],
    },
  },
};

// n8n Code node (Run Once for Each Item): never trust the model's output as-is.
// Checks the schema, verifies every evidence quote actually appears in the source
// document, cross-checks the deadline against SAM.gov metadata, and downgrades
// anything it cannot stand behind. Anything doubtful is flagged needs_review
// instead of being silently trusted or silently dropped.
const SCOPES = ['software_development', 'modernization', 'integration', 'data_analytics', 'ai_ml', 'infrastructure', 'staffing', 'hardware', 'other'];
const RECS = ['pursue', 'review', 'skip'];
const MAX_REMEMBERED = 5000;

const ctx = $('Build prompt').item.json;
const opp = ctx.opp;
const reasons = [];

const norm = (s) => String(s).toLowerCase().replace(/\s+/g, ' ').trim();
const haystack = norm(ctx.source_text);

const block = ($json.content || []).find((b) => b.type === 'tool_use' && b.name === 'record_analysis');
let a = block ? block.input : null;
if (!a) reasons.push('llm_call_failed');
if ($json.stop_reason === 'max_tokens') reasons.push('output_truncated');

let requirements = [];
if (a) {
  const bad = [];
  if (typeof a.summary !== 'string') bad.push('summary');
  if (!SCOPES.includes(a.scope_type)) bad.push('scope_type');
  if (!Number.isInteger(a.fit_score) || a.fit_score < 0 || a.fit_score > 100) bad.push('fit_score');
  if (!RECS.includes(a.recommendation)) bad.push('recommendation');
  if (typeof a.rationale !== 'string') bad.push('rationale');
  if (!Array.isArray(a.key_requirements)) bad.push('key_requirements');
  if (bad.length) {
    reasons.push(`schema_invalid:${bad.join('+')}`);
    a = null;
  }
}

if (a) {
  // Grounding check: a quote that is not in the document means the model made it up.
  let ungrounded = 0;
  for (const r of a.key_requirements) {
    const quote = r && typeof r.evidence_quote === 'string' ? norm(r.evidence_quote) : '';
    if (quote.length >= 8 && haystack.includes(quote)) requirements.push(r.requirement);
    else ungrounded += 1;
  }
  if (ungrounded) reasons.push(`ungrounded_quotes:${ungrounded}`);

  if (ctx.thin_source) {
    reasons.push('thin_source');
    a.fit_score = Math.min(a.fit_score, 60);
    if (a.recommendation === 'pursue') a.recommendation = 'review';
  }
  if (ungrounded && a.recommendation === 'pursue') a.recommendation = 'review';
  if (ctx.truncated) reasons.push('document_truncated');
  if (a.clearance_required === true) reasons.push('clearance_required');
}

// Metadata from SAM.gov is authoritative for the deadline; the model only fills gaps.
let deadline = opp.deadline ? opp.deadline.slice(0, 10) : '';
if (a && a.deadline_stated) {
  if (!deadline) deadline = a.deadline_stated;
  else if (deadline !== a.deadline_stated) reasons.push('deadline_mismatch');
}

// Only remember a notice once it was actually analysed, so failed runs retry it.
if (a) {
  const store = $getWorkflowStaticData('global');
  store.analyzedNoticeIds = [...(store.analyzedNoticeIds || []), opp.noticeId].slice(-MAX_REMEMBERED);
}

return {
  json: {
    notice_id: opp.noticeId,
    title: opp.title,
    agency: opp.agency,
    solicitation_number: opp.solicitationNumber,
    posted: opp.postedDate,
    deadline,
    naics: opp.naics,
    set_aside: (a && a.set_aside) || opp.setAside || '',
    scope_type: a ? a.scope_type : '',
    fit_score: a ? a.fit_score : '',
    recommendation: a ? a.recommendation : 'review',
    needs_review: reasons.length > 0,
    review_reasons: reasons.join('; '),
    summary: a ? a.summary : '',
    requirements: requirements.join(' | '),
    rationale: a ? a.rationale : '',
    risks: a && Array.isArray(a.risks) ? a.risks.join(' | ') : '',
    url: opp.uiLink,
    analyzed_at: new Date().toISOString(),
  },
};

// n8n Code node (Run Once for All Items): one email per run, best bids first.
// Emits nothing when no opportunity needs a human, so quiet days send no email.
const MIN_REVIEW_SCORE = 60;

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const rows = $input.all().map((i) => i.json);

const score = (r) => (typeof r.fit_score === 'number' ? r.fit_score : -1);
const pursue = rows.filter((r) => r.recommendation === 'pursue').sort((a, b) => score(b) - score(a));
const maybe = rows
  .filter((r) => r.recommendation === 'review' && !r.needs_review && score(r) >= MIN_REVIEW_SCORE)
  .sort((a, b) => score(b) - score(a));
const flagged = rows.filter((r) => r.needs_review && r.recommendation !== 'skip' && !pursue.includes(r) && !maybe.includes(r));

if (pursue.length + maybe.length + flagged.length === 0) return [];

const item = (r) =>
  `<li><a href="${esc(r.url)}">${esc(r.title)}</a> &mdash; ${esc(r.agency)}` +
  `${r.fit_score !== '' ? ` <b>[${esc(r.fit_score)}]</b>` : ''}` +
  `${r.deadline ? `, due ${esc(r.deadline)}` : ''}<br>${esc(r.summary)}` +
  `${r.needs_review ? `<br><i>Check before trusting: ${esc(r.review_reasons)}</i>` : ''}</li>`;

const section = (heading, list) => (list.length ? `<h3>${heading} (${list.length})</h3><ul>${list.map(item).join('')}</ul>` : '');

const html =
  section('Pursue', pursue) +
  section('Worth a look', maybe) +
  section('Needs a human (model output could not be fully verified)', flagged) +
  `<p><small>${rows.length} notices analysed. Every row is logged in the tracking sheet.</small></p>`;

const total = pursue.length + maybe.length + flagged.length;
return [{ json: { subject: `RFP Scout: ${pursue.length} to pursue, ${total - pursue.length} to check`, html } }];
